#!/usr/bin/env node
// Сборка бандлов классических скриптов: node tools/build-bundles.js [--check]
// Исходники js/*.js и js/app/*.js остаются источником правды; js/bundle.*.js — ГЕНЕРИРУЕМЫЕ файлы (коммитятся:
// GitHub Pages раздаёт main как есть, сборки на деплое нет). Модули склеиваются через "\n;\n" БЕЗ IIFE — общая
// глобальная лексическая область и семантика top-level const/let/function те же, что у отдельных <script>.
// Строгость: файл с "use strict" в начале делает строгим весь бандл, поэтому в одном бандле все файлы либо строгие, либо нет
// (инструмент это проверяет). Перед каждым модулем стоит маркер-комментарий с путём; синтаксис каждого модуля
// проверяется отдельно с его именем файла, так что ошибка указывает на исходник, а не на бандл.
"use strict";
const fs = require("fs");
const path = require("path");
const vm = require("vm");
const ROOT = path.resolve(__dirname, "..");

const appFiles = fs.readdirSync(path.join(ROOT, "js/app")).filter((f) => f.endsWith(".js")).sort().map((f) => "js/app/" + f);
const SKINS = ["cartoon", "comic", "watercolor", "neon", "steampunk", "gothic", "clay", "lego", "wood", "glass", "chalk", "newyear", "sakura", "vampire", "hacker", "pixel", "vaporwave", "ocean", "galaxy", "western", "sumie", "artdeco", "kawaii", "pirate", "medieval", "jungle", "arctic", "halloween", "retro", "newspaper", "blueprint"].map((s) => "js/skins/" + s + ".js");

// Порядок = порядок прежних <script src> в index.html (кроме vendor и discovery, см. README «Сборка бандлов»):
// vendor-библиотеки (qrcode/jsQR) остаются отдельными тегами и теперь стоят ПЕРЕД core — они независимы;
// discovery.js ("use strict") перенесён из середины core в начало app (стоял сразу перед webrtc/file-limits/emoji-data,
// которые его не используют на этапе загрузки), чтобы не смешивать строгие и нестрогие файлы в одном бандле.
const BUNDLES = [
  { out: "js/bundle.core.js", strict: false, files: ["js/i18n.js", "js/signaling-codec.js", "js/crypto-helper.js", "js/secure-store.js", "js/icons.js", "js/rich.js", "js/vendor/ml-kem768.js", "js/ratchet.js", "js/groupkeys.js", "js/groupadmin.js", "js/channels.js", "js/search.js", "js/linkauth.js", "js/signaling-client.js", "js/serverlist.js", "js/callquality.js", "js/webrtc.js", "js/file-limits.js", "js/bigfile.js", "js/emoji-data.js"] },
  { out: "js/bundle.app.js", strict: true, files: ["js/discovery.js", ...appFiles] },
  { out: "js/bundle.features.js", strict: false, files: ["js/stickers.js", "js/group-call.js", "js/framecrypt.js", "js/rooms.js", "js/localai.js", "js/devicecheck.js", "js/devicecert.js", "js/devicelink.js", "js/devices.js", "js/miniapps.js", "js/integrity.js", "tools/skin-contrast-lib.js", "js/themeeditor.js", "js/skins.js", ...SKINS, "js/skinfx.js"] },
  { out: "js/bundle.fx.js", strict: true, files: ["js/features.js", "js/features2.js"] },
];
// Порядок <script src> в index.html после сборки (бандлы + оставшиеся отдельные файлы).
const HTML_ORDER = ["js/languages-meta.js", "js/vendor/qrcode-generator.js", "js/vendor/qrcode-generator-utf8.js", "config.js", "js/release-key.js",
  "js/bundle.core.js", "js/bundle.app.js", "js/bundle.features.js", "js/bundle.fx.js", "js/easter.js"];

function read(p) { return fs.readFileSync(path.join(ROOT, p), "utf8").replace(/^﻿/, "").replace(/\r\n/g, "\n"); }
function isStrict(src) { return /^\s*(?:\/\/[^\n]*\n\s*|\/\*[\s\S]*?\*\/\s*)*["']use strict["']/.test(src); }

function build(b) {
  const parts = [];
  for (const f of b.files) {
    const src = read(f);
    try { new vm.Script(src, { filename: f }); } catch (e) { throw new Error("Синтаксическая ошибка в " + f + ": " + e.message); }
    if (isStrict(src) !== b.strict) throw new Error(f + ": строгость файла не совпадает с бандлом " + b.out + " (strict=" + b.strict + ")");
    parts.push("/* ==== " + f + " ==== */\n" + compact(src, f).replace(/\n+$/, "") + "\n");
  }
  const head = "/* GENERATED by tools/build-bundles.js — не править вручную. Источники: " + b.files.join(", ") + " */\n";
  return head + parts.join(";\n");
}

// V.88: компактная сборка — без комментариев и отступов (токены не трогаются: строки, шаблоны, регулярки остаются как есть;
// пробел между токенами — одним пробелом, перевод строки — одним \n, поэтому автоподстановка «;» работает как в исходнике).
// Исходники в js/ остаются с комментариями. Нужен acorn (tests/node_modules, ставится npm ci в tests).
let acorn = null;
try { acorn = require(path.join(ROOT, "tests/node_modules/acorn")); } catch (e) { acorn = null; }
function compact(src, name) {
  if (!acorn) throw new Error("build-bundles: нужен acorn — выполните npm ci в tests/");
  let out = "", prev = 0;
  const keep = []; // лицензионные комментарии сторонних модулей сохраняются (MIT и др. требуют сохранять уведомление)
  const onComment = (block, text, start, end) => { if (/@license|copyright|SPDX-License|\(c\)\s*\d{4}/i.test(text)) keep.push([start, end]); };
  try {
    for (const t of acorn.tokenizer(src, { ecmaVersion: "latest", allowHashBang: true, allowReturnOutsideFunction: true, onComment })) {
      const gap = src.slice(prev, t.start);
      const lic = keep.filter(([a0, b0]) => a0 >= prev && b0 <= t.start).map(([a0, b0]) => src.slice(a0, b0));
      if (lic.length) out += "\n" + lic.join("\n") + "\n";
      else if (gap) out += /[\n\r\u2028\u2029]/.test(gap) ? "\n" : " ";
      out += src.slice(t.start, t.end); prev = t.end;
    }
  } catch (e) { throw new Error(name + ": не удалось разобрать для компактной сборки: " + e.message); }
  return out;
}
function main() {
  const check = process.argv.includes("--check");
  if (check && !acorn) { console.warn("acorn не найден (cd tests && npm ci) — проверка бандлов пропущена"); return; } // напр. сборка зеркала на VPS
  let bad = 0;
  for (const b of BUNDLES) {
    const out = build(b), p = path.join(ROOT, b.out);
    if (check) {
      if (!fs.existsSync(p) || fs.readFileSync(p, "utf8") !== out) { console.error("УСТАРЕЛ: " + b.out + " — запустите node tools/build-bundles.js"); bad++; }
    } else { fs.writeFileSync(p, out); console.log(b.out + " " + out.length + " B, модулей: " + b.files.length); }
  }
  if (check) { if (bad) process.exit(1); console.log("бандлы актуальны"); }
}
if (require.main === module) main();
module.exports = { BUNDLES, HTML_ORDER, appFiles, build, compact };
